  };
  return <Range {...args} />;
}

import { Range } from '@refy-design/web';
import type { RangeValue } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof Range>, 'label'> = { label: 'Value range' };
  const [range, setRange] = useState<RangeValue>([20, 60]);
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <Range {...args} value={range} onChange={setRange} />
      <code
        style={{ fontFamily: 'var(--font-mono)', fontSize: 12, color: 'var(--ink-3)' }}
      >
        [{range[0]}, {range[1]}]
      </code>
    </div>
  );
}

